True def transform(grid):
    h, w = len(grid), len(grid[0])
    out = []
    for tile_r in range(3):
        for r in range(h):
            src_r = h - 1 - r if tile_r % 2 == 0 else r
            row = []
            for tile_c in range(2):
                if tile_c == 0:
                    row.extend(reversed(grid[src_r]))
                else:
                    row.extend(grid[src_r])
            out.append(row)
    return out
